// 检查权限
const status = photo.requestPermission();
if (status === 'authorized') {
  // 获取最近 5 张照片
  const photos = photo.getRecent({ limit: 5, mediaType: 'image' });
  console.log(`获取到 ${photos.length} 张照片:`, photos);

  if (photos.length > 0) {
    const b64 = photo.getBase64(photos[0].id);
    console.log('图片 Base64 长度:', b64.length);
  }
}
